/**
 * Creation of a compilable 8051 project (the µVision-compatible `.uvproj` XML) and
 * of starter source files.
 *
 * Everything here is derived from FACTS measured on this machine, not invented:
 *   - the node set and the memory layout come from a project that really builds
 *     (`demo/led.uvproj` → hex generated by the local toolchain);
 *   - `DEFAULT_DEVICE` is the device/vendor/cpu/deviceId triple that BOTH that
 *     project and the user's own project carry, so it is known-good here.
 *
 * What we deliberately do NOT do: ship any vendor file. The generated XML is our
 * own text, and `STARTUP.A51` is COPIED FROM THE USER'S INSTALL (BYOK) — never
 * bundled.
 *
 * Device list — CORRECTED 2026-10-17 (an earlier note here claimed the install
 * had no device database; that was wrong): the install DOES carry one, as
 * `UV4\UV4.cdb`, and Keil ships `UV4\UVCDB2XML.exe` to export it
 * (`-f UV4.cdb -a C51` → 1703 C51 devices / 77 vendors, ~0.1 s). That export has
 * name/vendor/header/description but NOT `DeviceId`, the `Cpu` memory string or
 * `<OnChipMemories>`, so the defaults below stay the one triple verified on this
 * machine. Measured: `UV4 -b` builds fine with `<DeviceId>` removed.
 */
import { outerBlocks } from './keil-core.mjs'

/**
 * Multi-project workspace (`.uvmpw`).
 *
 * The shape below is taken from µVision's OWN schema, `UV4\project_mpw.xsd`
 * (UTF-16), not from memory — which matters, because the member element is the
 * lowercase `<project>` and the batch-build switch is `NodeIsCheckedInBatchBuild`:
 *
 *   <ProjectWorkspace><SchemaVersion/><Header/><WorkspaceName/>
 *     <project><PathAndName/><NodeIsActive/><NodeIsExpanded/>
 *              <NodeIsCheckedInBatchBuild/><Sle7/>…</project>…
 *   </ProjectWorkspace>
 *
 * `Sle7` (µVision's own bookkeeping) is optional and we never write it.
 */
const xmlEscape = (value) =>
  String(value).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;')

/** One `<project>` member, as the schema orders its children. */
export function workspaceProjectEntry({ pathAndName, active = true, expanded = true, batchBuild = true }) {
  return [
    '  <project>',
    `    <PathAndName>${xmlEscape(pathAndName)}</PathAndName>`,
    `    <NodeIsActive>${active ? 1 : 0}</NodeIsActive>`,
    `    <NodeIsExpanded>${expanded ? 1 : 0}</NodeIsExpanded>`,
    `    <NodeIsCheckedInBatchBuild>${batchBuild ? 1 : 0}</NodeIsCheckedInBatchBuild>`,
    '  </project>',
  ].join('\n')
}

/** Build a `.uvmpw` for the given members (`pathAndName` values as written). */
export function workspaceXml({ name, projects = [] }) {
  return `<?xml version="1.0" encoding="UTF-8" standalone="no" ?>
<ProjectWorkspace xmlns:xsi="http://www.w3.org/2001/XMLSchema-instance" xsi:noNamespaceSchemaLocation="project_mpw.xsd">

  <SchemaVersion>1.0</SchemaVersion>

  <Header>Generated by Fixpoint</Header>

  <WorkspaceName>${xmlEscape(name)}</WorkspaceName>

${projects.map((entry) => workspaceProjectEntry(entry)).join('\n')}

</ProjectWorkspace>
`
}

/** Parse a `.uvmpw`. Returns the members with their raw `PathAndName` values. */
export function parseWorkspace(text) {
  const name = (/<WorkspaceName>([^<]*)<\/WorkspaceName>/.exec(text) ?? [])[1] ?? ''
  const projects = []
  // Members are lowercase `<project>`; `outerBlocks` handles the nesting.
  for (const body of outerBlocks(text, 'project')) {
    const pathAndName = (/<PathAndName>([^<]*)<\/PathAndName>/.exec(body) ?? [])[1]
    if (!pathAndName) continue
    const flag = (tag, fallback) => {
      const found = new RegExp(`<${tag}>([^<]*)</${tag}>`).exec(body)
      return found ? found[1].trim() !== '0' : fallback
    }
    projects.push({
      pathAndName: pathAndName.trim(),
      active: flag('NodeIsActive', true),
      expanded: flag('NodeIsExpanded', true),
      batchBuild: flag('NodeIsCheckedInBatchBuild', true),
    })
  }
  return { name: name.trim(), projects }
}
export const DEFAULT_DEVICE = {
  device: 'AT89C51',
  vendor: 'Microchip',
  cpu: 'IRAM(0-0x7F) IROM(0-0xFFF) CLOCK(24000000)',
  deviceId: '2976',
  registerFile: 'REGX51.H',
  iromSize: '0x1000',
  iramSize: '0x80',
}

const xml = (name) => `<${name}></${name}>`

/** One `<File>` entry as µVision writes it (FileType 1 = C source, 2 = assembler). */
function fileEntry(name, fileType, indent = '            ') {
  const escaped = String(name).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;')
  return [
    `${indent}<File>`,
    `${indent}  <FileName>${escaped}</FileName>`,
    `${indent}  <FileType>${fileType}</FileType>`,
    `${indent}  <FilePath>.\\${escaped}</FilePath>`,
    `${indent}</File>`,
  ].join('\n')
}

/**
 * A complete, minimal target. The debug/utilities/DLL blocks of a µVision file are
 * omitted on purpose: `UV4 -b` does not need them, and dropping them keeps vendor
 * strings out of what we generate.
 */
export function c51ProjectXml({
  targetName = 'Target 1',
  outputName,
  device = DEFAULT_DEVICE,
  files = [],
} = {}) {
  const names = files.length ? files : [{ name: 'main.c', fileType: 1 }]
  return `<?xml version="1.0" encoding="UTF-8" standalone="no" ?>
<Project xmlns:xsi="http://www.w3.org/2001/XMLSchema-instance" xsi:noNamespaceSchemaLocation="project_proj.xsd">

  <SchemaVersion>1.1</SchemaVersion>

  <!-- Generated by 8051 Studio. Editable in any editor; keep the tag names as they are. -->

  <Targets>
    <Target>
      <TargetName>${targetName}</TargetName>
      <ToolsetNumber>0x0</ToolsetNumber>
      <ToolsetName>MCS-51</ToolsetName>
      <uAC6>0</uAC6>
      <TargetOption>
        <TargetCommonOption>
          <Device>${device.device}</Device>
          <Vendor>${device.vendor}</Vendor>
          <Cpu>${device.cpu ?? ''}</Cpu>
${xml('FlashUtilSpec')}
          <StartupFile>"LIB\\STARTUP.A51" ("Standard 8051 Startup Code")</StartupFile>
${xml('FlashDriverDll')}
${device.deviceId ? `          <DeviceId>${device.deviceId}</DeviceId>\n` : ''}          <RegisterFile>${device.registerFile}</RegisterFile>
          <OutputDirectory>.\\Objects\\</OutputDirectory>
          <OutputName>${outputName}</OutputName>
          <CreateExecutable>1</CreateExecutable>
          <CreateLib>0</CreateLib>
          <CreateHexFile>1</CreateHexFile>
          <DebugInformation>1</DebugInformation>
          <BrowseInformation>1</BrowseInformation>
          <ListingPath>.\\Listings\\</ListingPath>
          <HexFormatSelection>0</HexFormatSelection>
          <Merge32K>0</Merge32K>
          <CreateBatchFile>0</CreateBatchFile>
          <!-- 1 = participate in µVision's own Batch Build. Measured: with 0 the
               project is reported as "skipped" and no hex is produced. -->
          <SelectedForBatchBuild>1</SelectedForBatchBuild>
          <SVCSIdString></SVCSIdString>
        </TargetCommonOption>
        <CommonProperty>
          <UseCPPCompiler>0</UseCPPCompiler>
          <IncludeInBuild>1</IncludeInBuild>
          <AlwaysBuild>0</AlwaysBuild>
          <StopOnExitCode>3</StopOnExitCode>
          <CustomArgument></CustomArgument>
          <IncludeLibraryModules></IncludeLibraryModules>
          <ComprImg>1</ComprImg>
        </CommonProperty>
        <Target51>
          <Target51Misc>
            <MemoryModel>0</MemoryModel>
            <RTOS>0</RTOS>
            <RomSize>2</RomSize>
            <UseOnchipRom>0</UseOnchipRom>
            <HadIRAM>1</HadIRAM>
            <HadXRAM>0</HadXRAM>
            <HadIROM>1</HadIROM>
            <OnChipMemories>
              <IRO>
                <Type>1</Type>
                <StartAddress>0x0</StartAddress>
                <Size>${device.iromSize || '0x0'}</Size>
              </IRO>
              <IRA>
                <Type>0</Type>
                <StartAddress>0x0</StartAddress>
                <Size>${device.iramSize || '0x0'}</Size>
              </IRA>
              <XRA>
                <Type>0</Type>
                <StartAddress>0x0</StartAddress>
                <Size>${device.xramSize || '0x0'}</Size>
              </XRA>
            </OnChipMemories>
          </Target51Misc>
          <C51>
            <RegisterColoring>0</RegisterColoring>
            <VariablesInOrder>0</VariablesInOrder>
            <IntegerPromotion>1</IntegerPromotion>
            <uAregs>0</uAregs>
            <UseInterruptVector>1</UseInterruptVector>
            <Fuzzy>3</Fuzzy>
            <Optimize>8</Optimize>
            <WarningLevel>2</WarningLevel>
            <SizeSpeed>1</SizeSpeed>
            <ObjectExtend>1</ObjectExtend>
            <ACallAJmp>0</ACallAJmp>
            <InterruptVectorAddress>0</InterruptVectorAddress>
            <VariousControls>
              <MiscControls></MiscControls>
              <Define></Define>
              <Undefine></Undefine>
              <IncludePath></IncludePath>
            </VariousControls>
          </C51>
          <Ax51>
            <UseMpl>0</UseMpl>
            <UseStandard>1</UseStandard>
            <UseCase>0</UseCase>
            <UseMod51>0</UseMod51>
            <VariousControls>
              <MiscControls></MiscControls>
              <Define></Define>
              <Undefine></Undefine>
              <IncludePath></IncludePath>
            </VariousControls>
          </Ax51>
          <Lx51>
            <useFile>0</useFile>
            <linkonly>0</linkonly>
            <UseMemoryFromTarget>1</UseMemoryFromTarget>
            <CaseSensitiveSymbols>0</CaseSensitiveSymbols>
            <WarningLevel>2</WarningLevel>
            <DataOverlaying>1</DataOverlaying>
            <OverlayString></OverlayString>
            <MiscControls></MiscControls>
            <DisableWarningNumbers></DisableWarningNumbers>
            <LinkerCmdFile></LinkerCmdFile>
            <Assign></Assign>
            <ReserveString></ReserveString>
            <CClasses></CClasses>
            <UserClasses></UserClasses>
            <CSection></CSection>
            <UserSection></UserSection>
            <CodeBaseAddress></CodeBaseAddress>
            <XDataBaseAddress></XDataBaseAddress>
            <PDataBaseAddress></PDataBaseAddress>
            <BitBaseAddress></BitBaseAddress>
            <DataBaseAddress></DataBaseAddress>
            <IDataBaseAddress></IDataBaseAddress>
            <Precede></Precede>
            <Stack></Stack>
            <CodeSegmentName></CodeSegmentName>
            <XDataSegmentName></XDataSegmentName>
            <BitSegmentName></BitSegmentName>
            <DataSegmentName></DataSegmentName>
            <IDataSegmentName></IDataSegmentName>
          </Lx51>
        </Target51>
      </TargetOption>
      <Groups>
        <Group>
          <GroupName>Source Group 1</GroupName>
          <Files>
${names.map((entry) => fileEntry(entry.name, entry.fileType ?? 1)).join('\n')}
          </Files>
        </Group>
      </Groups>
    </Target>
  </Targets>

</Project>
`
}

/**
 * A minimal, obviously-correct starting point for a C51 source file. Written
 * WITHOUT a byte-order mark, because the compiler would otherwise report those
 * three bytes as unprintable characters.
 *
 * `withMain` is only for the entry file of a brand-new project. An extra source
 * file must NOT define `main` — two of them break the link ("multiple public
 * definitions"), which the acceptance test caught on the second file.
 */
export function starterSource(name, { withMain = false } = {}) {
  const lower = String(name).toLowerCase()
  const guard = `${String(name).replace(/[^A-Za-z0-9]/g, '_').toUpperCase()}_H`
  if (lower.endsWith('.h')) {
    return `#ifndef ${guard}\n#define ${guard}\n\n\n\n#endif\n`
  }
  if (lower.endsWith('.c')) {
    if (withMain) {
      return [
        '#include <reg51.h>',
        '',
        'void main(void)',
        '{',
        '    while (1)',
        '    {',
        '    }',
        '}',
        '',
      ].join('\n')
    }
    return ['#include <reg51.h>', '', '/* 在这里写你的函数 */', ''].join('\n')
  }
  if (lower.endsWith('.a51') || lower.endsWith('.s')) {
    return ['; ' + name, '', '        ORG     0000H', '        LJMP    MAIN', '', 'MAIN:', '        SJMP    $', '', '        END', ''].join(
      '\n',
    )
  }
  return ''
}
